<script setup lang="ts">
import { computed, shallowRef, watch } from 'vue';
import { Workflow, LayoutDashboard, History, Database, ArrowUpRight, ChevronRight, RefreshCw, Play, CircleCheck, Clock3, Layers, GitBranch, FlaskConical, CircleAlert, ArrowRight, ShieldCheck, LoaderCircle, X } from '@lucide/vue';
import { useDelivery, formatTime, runStatusLabel, sourceStatusLabel } from './useDelivery';
import RequirementList from './RequirementList.vue';
import WorkflowCanvas from './WorkflowCanvas.vue';
import RunInspector from './RunInspector.vue';
import ThemePicker from '../../shared/theme/ThemePicker.vue';

const { query, selected, currentRun, visibleRequirements, search, scenario, page, notice, busy, selectRequirement, selectRun, start, refresh, resume, rework } = useDelivery();
const data = query.data;
const selectedStep = shallowRef('freeze-source');
watch(() => [currentRun.value?.runId, currentRun.value?.status], () => {
  selectedStep.value = currentRun.value?.steps.find((item) => item.status === 'suspended' || item.status === 'running')?.id ?? (currentRun.value?.status === 'success' ? 'delivery-receipt' : 'freeze-source');
});
const runCounts = computed(() => ({ total: data.value?.runs.length ?? 0, waiting: data.value?.runs.filter((run) => run.status === 'suspended').length ?? 0, completed: data.value?.runs.filter((run) => run.status === 'success').length ?? 0 }));
const currentTitle = computed(() => ({ workflow: '交付工作流', history: '运行记录', source: '来源快照' })[page.value]);
const sourceLabel = computed(() => data.value?.source.origin === 'live' ? '交付数据已连接' : '使用缓存快照');
</script>

<template>
  <div class="app-shell">
    <aside class="sidebar">
      <div class="brand"><div class="brand-mark"><Workflow :size="23" /></div><div><strong>Delivery Lab</strong><span>POWERED BY MASTRA</span></div></div>
      <div class="workspace-picker"><span class="workspace-avatar">A</span><div><strong>APEX 工作空间</strong><span>本地实验环境</span></div><ChevronRight :size="14" /></div>
      <div class="nav-caption">WORKSPACE</div>
      <nav aria-label="主导航"><button :class="{ active: page === 'workflow' }" @click="page = 'workflow'"><LayoutDashboard :size="17" />交付工作流<span class="nav-dot"></span></button><button :class="{ active: page === 'history' }" @click="page = 'history'"><History :size="17" />运行记录<span class="nav-counter">{{ runCounts.total }}</span></button><button :class="{ active: page === 'source' }" @click="page = 'source'"><Database :size="17" />来源快照</button></nav>
      <div class="sidebar-note"><FlaskConical :size="20" /><strong>在这里试跑你的流程</strong><p>使用真实 Mastra 引擎，体验证据暂停、审核与恢复。</p><span>演示执行 · 独立存储</span></div>
      <div class="sidebar-bottom"><RouterLink to="/catchup/merge">打开合入面板 <ArrowUpRight :size="15" /></RouterLink><div class="engine-status"><span class="live-dot"></span>Mastra 1.64.0 <span>LOCAL</span></div></div>
    </aside>

    <main class="main-content">
      <header class="topbar"><div class="breadcrumb">APEX <ChevronRight :size="13" /><span>{{ currentTitle }}</span></div><div class="topbar-right"><span class="connection"><span class="live-dot"></span>{{ data ? sourceLabel : '连接中' }}</span><span class="mode-badge"><FlaskConical :size="13" />演示环境</span><ThemePicker /></div></header>
      <div class="page-content">
        <div class="page-heading"><div><div class="eyebrow">DEVELOPMENT DELIVERY</div><h1>{{ currentTitle }}<span class="version">LAB / 01</span></h1><p>让每次交付都经过清晰的步骤，停在需要你判断的地方。</p></div><button class="btn" :disabled="busy" @click="refresh"><RefreshCw :size="14" :class="{ spin: busy }" />刷新来源</button></div>
        <div v-if="notice || query.error.value" class="global-error" role="alert"><CircleAlert :size="16" /><span>{{ notice || query.error.value?.message }}</span><button aria-label="关闭提示" @click="notice = ''"><X :size="14" /></button></div>
        <div v-if="!data" class="loading-state"><LoaderCircle :size="27" class="spin" /><h2>正在连接工作流引擎</h2><p>读取需求快照和已保存的运行记录</p></div>
        <template v-else>
          <section class="metrics" aria-label="工作流统计"><div><span class="metric-label">来源需求 <Database :size="15" /></span><strong>{{ data.source.requirements.length }}<small>项</small></strong><span class="metric-note">内嵌后端只读快照</span></div><div><span class="metric-label">本原型运行 <Layers :size="15" /></span><strong>{{ runCounts.total }}<small>次</small></strong><span class="metric-note">由 Mastra 独立编排</span></div><div><span class="metric-label">等待输入 <Clock3 :size="15" /></span><strong class="amber">{{ runCounts.waiting }}<small>次</small></strong><span class="metric-note">状态已保存，可随时继续</span></div><div><span class="metric-label">演示完成 <CircleCheck :size="15" /></span><strong class="green">{{ runCounts.completed }}<small>次</small></strong><span class="metric-note">不代表真实 Git / Jira 交付</span></div></section>

          <div v-if="page === 'workflow'" class="workspace-grid">
            <RequirementList v-model:search="search" :items="visibleRequirements" :selected-id="selected?.id" :total="data.source.requirements.length" @select="selectRequirement" />
            <section v-if="selected" class="workflow-panel">
              <div class="workflow-header"><div class="workflow-title"><span class="overline">{{ selected.id }} <span> / </span> {{ selected.jiraKey }}</span><h2>{{ selected.title }}</h2><div class="branch-label"><GitBranch :size="13" /><span>{{ selected.sourceBranch }}</span></div></div><span v-if="currentRun" class="run-badge" :class="currentRun.status"><span class="live-dot"></span>{{ runStatusLabel(currentRun) }}</span><span v-else class="run-badge neutral">尚未运行</span></div>
              <div class="run-controls"><label>演示场景<select v-model="scenario" aria-label="演示场景"><option value="standard">顺利交付</option><option value="missing-evidence">缺少测试数据</option><option value="merge-conflict">合入产生冲突</option></select></label><span class="analysis-mode"><span class="live-dot"></span>{{ data.engine.model ? '模型分析已配置' : '范围分析：规则模式' }}</span><button class="btn primary" :disabled="busy || currentRun?.status === 'running'" @click="start"><LoaderCircle v-if="busy" :size="14" class="spin" /><Play v-else :size="14" />{{ currentRun ? '新建演示运行' : '开始演示' }}</button></div>
              <WorkflowCanvas :run="currentRun" :selected-step="selectedStep" @select="selectedStep = $event" />
              <RunInspector :requirement="currentRun?.requirement ?? selected" :run="currentRun" :busy="busy" :selected-step="selectedStep" @resume="resume" @rework="rework" />
              <footer class="workflow-footer"><ShieldCheck :size="13" /><span>{{ data.engine.storage }}</span><span v-if="currentRun" class="mono run-id" :title="currentRun.runId">RUN {{ currentRun.runId.slice(0, 8) }}</span><span v-else class="run-id">先开始一次演示运行</span></footer>
            </section>
          </div>

          <section v-else-if="page === 'history'" class="table-panel"><div class="table-heading"><h2>每一轮都有迹可循</h2><span>旧运行和暂停证据会保留</span></div><div v-if="!data.runs.length" class="empty"><History :size="28" /><p>还没有运行记录</p><button class="btn primary" @click="page = 'workflow'">开始第一个演示 <ArrowRight :size="14" /></button></div><div v-else class="table-scroll"><table><thead><tr><th>需求 / 本轮运行</th><th>演示场景</th><th>状态</th><th>创建时间</th><th></th></tr></thead><tbody><tr v-for="run in data.runs" :key="run.runId"><td><strong>{{ run.requirement.title }}</strong><span class="table-secondary mono">{{ run.requirement.id }} · {{ run.runId.slice(0, 8) }}{{ run.parentRunId ? ' · 重新预演' : '' }}</span></td><td>{{ run.scenario === 'standard' ? '顺利交付' : run.scenario === 'missing-evidence' ? '缺少测试数据' : '合入产生冲突' }}</td><td><span class="run-badge" :class="run.status">{{ runStatusLabel(run) }}</span></td><td class="mono muted">{{ formatTime(run.createdAt) }}</td><td><button class="text-button" @click="selectRun(run)">查看 <ArrowRight :size="14" /></button></td></tr></tbody></table></div></section>

          <section v-else class="table-panel"><div class="table-heading"><div><h2>交付来源快照</h2><p>来源记录独立展示，不会被本原型的演示结果覆盖。</p></div><span class="mono">REV {{ data.source.revision }}</span></div><div class="source-metadata"><span><GitBranch :size="14" />{{ data.source.targetBranch }}</span><span>读取于 {{ formatTime(data.source.fetchedAt) }}</span></div><div class="table-scroll"><table><thead><tr><th>需求</th><th>来源状态</th><th>通过 / 跳过 / 缺口</th><th>查看</th></tr></thead><tbody><tr v-for="item in data.source.requirements" :key="item.id"><td><strong>{{ item.title }}</strong><span class="table-secondary mono">{{ item.id }} · {{ item.jiraKey }}</span></td><td>{{ sourceStatusLabel(item.sourceStatus) }}</td><td>{{ item.evidence.passed }} / {{ item.evidence.skipped }} / {{ item.evidence.failed + item.evidence.missing }}</td><td><button class="text-button" @click="selectRequirement(item.id); page = 'workflow'">进入实验 <ArrowRight :size="14" /></button></td></tr></tbody></table></div></section>
          <div class="page-footer"><span>DELIVERY LAB <i>/</i> LOCAL PROTOTYPE</span><span>{{ data.source.message }}</span></div>
        </template>
      </div>
    </main>
  </div>
</template>

<style scoped>
